import time
import numpy as np

def Hbar_full_ncomm1_nbody1(HBar, h, t, gamma1, eta1, lambdas, orbspace, verbose=False):
    tic = time.time()
    c = orbspace['core_alpha']
    C = orbspace['core_beta']
    a = orbspace['active_alpha']
    A = orbspace['active_beta']
    v = orbspace['virt_alpha']
    V = orbspace['virt_beta']
    hc = orbspace['hole_core_alpha']
    hC = orbspace['hole_core_beta']
    ha = orbspace['hole_active_alpha']
    hA = orbspace['hole_active_beta']
    pa = orbspace['particle_active_alpha']
    pA = orbspace['particle_active_beta']
    pv = orbspace['particle_virt_alpha']
    pV = orbspace['particle_virt_beta']

    # A|A
    HBar['b'][A,A] += -1.0 * np.einsum('uv,wx,xIuU,vVwI->VU', eta1['a'], gamma1['a'], h['ab'][a,C,a,A], t['ab'][pa,pA,ha,hC], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('uv,wx,xUuA,vAwV->UV', eta1['a'], gamma1['a'], h['ab'][a,A,a,V], t['ab'][pa,pV,ha,hA], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('uv,WX,iXuU,vViW->VU', eta1['a'], gamma1['b'], h['ab'][c,A,a,A], t['ab'][pa,pA,hc,hA], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('uv,iu,vUiV->UV', eta1['a'], h['a'][c,a], t['ab'][pa,pA,hc,hA], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('uv,iIuU,vViI->VU', eta1['a'], h['ab'][c,C,a,A], t['ab'][pa,pA,hc,hC], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('uv,iUuV,vi->UV', eta1['a'], h['ab'][c,A,a,A], t['a'][pa,hc], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('uv,iUuA,vAiV->UV', eta1['a'], h['ab'][c,A,a,V], t['ab'][pa,pV,hc,hA], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('WX,uv,iUuW,vXiV->UV', eta1['b'], eta1['a'], h['ab'][c,A,a,A], t['ab'][pa,pA,hc,hA], optimize=True)
    HBar['b'][A,A] += 0.5 * np.einsum('WX,YZ,IUWY,XZIV->UV', eta1['b'], eta1['b'], h['bb'][C,A,A,A], t['bb'][pA,pA,hC,hA], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('WX,uv,vUaW,aXuV->UV', eta1['b'], gamma1['a'], h['ab'][a,A,v,A], t['ab'][pv,pA,ha,hA], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('WX,YZ,IZUW,VXIY->VU', eta1['b'], gamma1['b'], h['bb'][C,A,A,A], t['bb'][pA,pA,hC,hA], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('WX,YZ,UZWA,XAVY->UV', eta1['b'], gamma1['b'], h['bb'][A,A,A,V], t['bb'][pA,pV,hA,hA], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('WX,iUaW,aXiV->UV', eta1['b'], h['ab'][c,A,v,A], t['ab'][pv,pA,hc,hA], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('WX,IW,UXIV->UV', eta1['b'], h['b'][C,A], t['bb'][pA,pA,hC,hA], optimize=True)
    HBar['b'][A,A] += -0.5 * np.einsum('WX,IJUW,VXIJ->VU', eta1['b'], h['bb'][C,C,A,A], t['bb'][pA,pA,hC,hC], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('WX,IUVW,XI->UV', eta1['b'], h['bb'][C,A,A,A], t['b'][pA,hC], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('WX,IUWA,XAIV->UV', eta1['b'], h['bb'][C,A,A,V], t['bb'][pA,pV,hC,hA], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('uv,va,aUuV->UV', gamma1['a'], h['a'][a,v], t['ab'][pv,pA,ha,hA], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('uv,vIaU,aVuI->VU', gamma1['a'], h['ab'][a,C,v,A], t['ab'][pv,pA,ha,hC], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('uv,vUaV,au->UV', gamma1['a'], h['ab'][a,A,v,A], t['a'][pv,ha], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('uv,vUaA,aAuV->UV', gamma1['a'], h['ab'][a,A,v,V], t['ab'][pv,pV,ha,hA], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('WX,uv,vXaU,aVuW->VU', gamma1['b'], gamma1['a'], h['ab'][a,A,v,A], t['ab'][pv,pA,ha,hA], optimize=True)
    HBar['b'][A,A] += -0.5 * np.einsum('WX,YZ,XZUA,VAWY->VU', gamma1['b'], gamma1['b'], h['bb'][A,A,A,V], t['bb'][pA,pV,hA,hA], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('WX,iXaU,aViW->VU', gamma1['b'], h['ab'][c,A,v,A], t['ab'][pv,pA,hc,hA], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('WX,IXUA,VAIW->VU', gamma1['b'], h['bb'][C,A,A,V], t['bb'][pA,pV,hC,hA], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('WX,UXVA,AW->UV', gamma1['b'], h['bb'][A,A,A,V], t['b'][pV,hA], optimize=True)
    HBar['b'][A,A] += 0.5 * np.einsum('WX,UXAB,ABVW->UV', gamma1['b'], h['bb'][A,A,V,V], t['bb'][pV,pV,hA,hA], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('WX,XA,UAVW->UV', gamma1['b'], h['b'][A,V], t['bb'][pA,pV,hA,hA], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('ia,aUiV->UV', h['a'][c,v], t['ab'][pv,pA,hc,hA], optimize=True)
    HBar['b'][A,A] += 0.5 * np.einsum('iuvw,vwux,xUiV->UV', h['aa'][c,a,a,a], lambdas['aa'], t['ab'][pa,pA,hc,hA], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('iIaU,aViI->VU', h['ab'][c,C,v,A], t['ab'][pv,pA,hc,hC], optimize=True)
    HBar['b'][A,A] += -0.5 * np.einsum('iUuV,uvwx,wxiv->UV', h['ab'][c,A,a,A], lambdas['aa'], t['aa'][pa,pa,hc,ha], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('iUuV,uWvX,vXiW->UV', h['ab'][c,A,a,A], lambdas['ab'], t['ab'][pa,pA,hc,hA], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('iUuW,uWvX,vXiV->UV', h['ab'][c,A,a,A], lambdas['ab'], t['ab'][pa,pA,hc,hA], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('iUaV,ai->UV', h['ab'][c,A,v,A], t['a'][pv,hc], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('iUaA,aAiV->UV', h['ab'][c,A,v,V], t['ab'][pv,pV,hc,hA], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('iWuU,uXvW,vViX->VU', h['ab'][c,A,a,A], lambdas['ab'], t['ab'][pa,pA,hc,hA], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('iWuX,uXvW,vUiV->UV', h['ab'][c,A,a,A], lambdas['ab'], t['ab'][pa,pA,hc,hA], optimize=True)
    HBar['b'][A,A] += 0.5 * np.einsum('uvwa,wxuv,aUxV->UV', h['aa'][a,a,a,v], lambdas['aa'], t['ab'][pv,pA,ha,hA], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('uIvU,vwux,xVwI->VU', h['ab'][a,C,a,A], lambdas['aa'], t['ab'][pa,pA,ha,hC], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('uIvU,vWuX,VXIW->VU', h['ab'][a,C,a,A], lambdas['ab'], t['bb'][pA,pA,hC,hA], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('uIvW,vWuX,UXIV->UV', h['ab'][a,C,a,A], lambdas['ab'], t['bb'][pA,pA,hC,hA], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('uUvA,vwux,xAwV->UV', h['ab'][a,A,a,V], lambdas['aa'], t['ab'][pa,pV,ha,hA], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('uUvA,vWuX,XAVW->UV', h['ab'][a,A,a,V], lambdas['ab'], t['bb'][pA,pV,hA,hA], optimize=True)
    HBar['b'][A,A] += -0.5 * np.einsum('uUaV,vwux,xavw->UV', h['ab'][a,A,v,A], lambdas['aa'], t['aa'][pa,pv,ha,ha], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('uUaV,vWuX,aXvW->UV', h['ab'][a,A,v,A], lambdas['ab'], t['ab'][pv,pA,ha,hA], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('uUaW,vWuX,aXvV->UV', h['ab'][a,A,v,A], lambdas['ab'], t['ab'][pv,pA,ha,hA], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('uWvA,vXuW,UAVX->UV', h['ab'][a,A,a,V], lambdas['ab'], t['bb'][pA,pV,hA,hA], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('uWaU,vXuW,aVvX->VU', h['ab'][a,A,v,A], lambdas['ab'], t['ab'][pv,pA,ha,hA], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('uWaX,vXuW,aUvV->UV', h['ab'][a,A,v,A], lambdas['ab'], t['ab'][pv,pA,ha,hA], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('IU,VI->VU', h['b'][C,A], t['b'][pA,hC], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('IA,UAIV->UV', h['b'][C,V], t['bb'][pA,pV,hC,hA], optimize=True)
    HBar['b'][A,A] += -0.5 * np.einsum('IJUA,VAIJ->VU', h['bb'][C,C,A,V], t['bb'][pA,pV,hC,hC], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('IUVW,uWvX,vXuI->UV', h['bb'][C,A,A,A], lambdas['ab'], t['ab'][pa,pA,ha,hC], optimize=True)
    HBar['b'][A,A] += 0.5 * np.einsum('IUVW,WXYZ,YZIX->UV', h['bb'][C,A,A,A], lambdas['bb'], t['bb'][pA,pA,hC,hA], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('IUVA,AI->UV', h['bb'][C,A,A,V], t['b'][pV,hC], optimize=True)
    HBar['b'][A,A] += 0.25 * np.einsum('IUWX,WXYZ,YZIV->UV', h['bb'][C,A,A,A], lambdas['bb'], t['bb'][pA,pA,hC,hA], optimize=True)
    HBar['b'][A,A] += 0.5 * np.einsum('IUAB,ABIV->UV', h['bb'][C,A,V,V], t['bb'][pV,pV,hC,hA], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('IWUX,uXvW,vVuI->VU', h['bb'][C,A,A,A], lambdas['ab'], t['ab'][pa,pA,ha,hC], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('IWUX,XYWZ,VZIY->VU', h['bb'][C,A,A,A], lambdas['bb'], t['bb'][pA,pA,hC,hA], optimize=True)
    HBar['b'][A,A] += -0.5 * np.einsum('IWXY,XYWZ,UZIV->UV', h['bb'][C,A,A,A], lambdas['bb'], t['bb'][pA,pA,hC,hA], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('UA,AV->UV', h['b'][A,V], t['b'][pV,hA], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('UWVA,uXvW,vAuX->UV', h['bb'][A,A,A,V], lambdas['ab'], t['ab'][pa,pV,ha,hA], optimize=True)
    HBar['b'][A,A] += -0.5 * np.einsum('UWVA,XYWZ,ZAXY->UV', h['bb'][A,A,A,V], lambdas['bb'], t['bb'][pA,pV,hA,hA], optimize=True)
    HBar['b'][A,A] += -1.0 * np.einsum('UWXA,uXvW,vAuV->UV', h['bb'][A,A,A,V], lambdas['ab'], t['ab'][pa,pV,ha,hA], optimize=True)
    HBar['b'][A,A] += 1.0 * np.einsum('UWXA,XYWZ,ZAVY->UV', h['bb'][A,A,A,V], lambdas['bb'], t['bb'][pA,pV,hA,hA], optimize=True)
    HBar['b'][A,A] += -0.25 * np.einsum('WXUA,YZWX,VAYZ->VU', h['bb'][A,A,A,V], lambdas['bb'], t['bb'][pA,pV,hA,hA], optimize=True)
    HBar['b'][A,A] += 0.5 * np.einsum('WXYA,YZWX,UAVZ->UV', h['bb'][A,A,A,V], lambdas['bb'], t['bb'][pA,pV,hA,hA], optimize=True)
    # A|C
    HBar['b'][C,A] += 1.0 * np.einsum('uv,wx,xIuA,vAwU->IU', eta1['a'], gamma1['a'], h['ab'][a,C,a,V], t['ab'][pa,pV,ha,hA], optimize=True)
    HBar['b'][C,A] += 1.0 * np.einsum('uv,iIuU,vi->IU', eta1['a'], h['ab'][c,C,a,A], t['a'][pa,hc], optimize=True)
    HBar['b'][C,A] += 1.0 * np.einsum('uv,iIuA,vAiU->IU', eta1['a'], h['ab'][c,C,a,V], t['ab'][pa,pV,hc,hA], optimize=True)
    HBar['b'][C,A] += 1.0 * np.einsum('VW,uv,iIuV,vWiU->IU', eta1['b'], eta1['a'], h['ab'][c,C,a,A], t['ab'][pa,pA,hc,hA], optimize=True)
    HBar['b'][C,A] += -0.5 * np.einsum('VW,XY,IJVX,WYJU->IU', eta1['b'], eta1['b'], h['bb'][C,C,A,A], t['bb'][pA,pA,hC,hA], optimize=True)
    HBar['b'][C,A] += 1.0 * np.einsum('VW,uv,vIaV,aWuU->IU', eta1['b'], gamma1['a'], h['ab'][a,C,v,A], t['ab'][pv,pA,ha,hA], optimize=True)
    HBar['b'][C,A] += 1.0 * np.einsum('VW,XY,IYVA,WAUX->IU', eta1['b'], gamma1['b'], h['bb'][C,A,A,V], t['bb'][pA,pV,hA,hA], optimize=True)
    HBar['b'][C,A] += 1.0 * np.einsum('VW,iIaV,aWiU->IU', eta1['b'], h['ab'][c,C,v,A], t['ab'][pv,pA,hc,hA], optimize=True)
    HBar['b'][C,A] += 1.0 * np.einsum('VW,IJUV,WJ->IU', eta1['b'], h['bb'][C,C,A,A], t['b'][pA,hC], optimize=True)
    HBar['b'][C,A] += -1.0 * np.einsum('VW,IJVA,WAJU->IU', eta1['b'], h['bb'][C,C,A,V], t['bb'][pA,pV,hC,hA], optimize=True)
    HBar['b'][C,A] += 1.0 * np.einsum('uv,vIaU,au->IU', gamma1['a'], h['ab'][a,C,v,A], t['a'][pv,ha], optimize=True)
    HBar['b'][C,A] += 1.0 * np.einsum('uv,vIaA,aAuU->IU', gamma1['a'], h['ab'][a,C,v,V], t['ab'][pv,pV,ha,hA], optimize=True)
    HBar['b'][C,A] += 1.0 * np.einsum('VW,IWUA,AV->IU', gamma1['b'], h['bb'][C,A,A,V], t['b'][pV,hA], optimize=True)
    HBar['b'][C,A] += 0.5 * np.einsum('VW,IWAB,ABUV->IU', gamma1['b'], h['bb'][C,A,V,V], t['bb'][pV,pV,hA,hA], optimize=True)
    HBar['b'][C,A] += -0.5 * np.einsum('iIuU,uvwx,wxiv->IU', h['ab'][c,C,a,A], lambdas['aa'], t['aa'][pa,pa,hc,ha], optimize=True)
    HBar['b'][C,A] += -1.0 * np.einsum('iIuU,uVvW,vWiV->IU', h['ab'][c,C,a,A], lambdas['ab'], t['ab'][pa,pA,hc,hA], optimize=True)
    HBar['b'][C,A] += 1.0 * np.einsum('iIuV,uVvW,vWiU->IU', h['ab'][c,C,a,A], lambdas['ab'], t['ab'][pa,pA,hc,hA], optimize=True)
    HBar['b'][C,A] += 1.0 * np.einsum('iIaU,ai->IU', h['ab'][c,C,v,A], t['a'][pv,hc], optimize=True)
    HBar['b'][C,A] += 1.0 * np.einsum('iIaA,aAiU->IU', h['ab'][c,C,v,V], t['ab'][pv,pV,hc,hA], optimize=True)
    HBar['b'][C,A] += 1.0 * np.einsum('uIvA,vwux,xAwU->IU', h['ab'][a,C,a,V], lambdas['aa'], t['ab'][pa,pV,ha,hA], optimize=True)
    HBar['b'][C,A] += -1.0 * np.einsum('uIvA,vVuW,WAUV->IU', h['ab'][a,C,a,V], lambdas['ab'], t['bb'][pA,pV,hA,hA], optimize=True)
    HBar['b'][C,A] += -0.5 * np.einsum('uIaU,vwux,xavw->IU', h['ab'][a,C,v,A], lambdas['aa'], t['aa'][pa,pv,ha,ha], optimize=True)
    HBar['b'][C,A] += 1.0 * np.einsum('uIaU,vVuW,aWvV->IU', h['ab'][a,C,v,A], lambdas['ab'], t['ab'][pv,pA,ha,hA], optimize=True)
    HBar['b'][C,A] += -1.0 * np.einsum('uIaV,vVuW,aWvU->IU', h['ab'][a,C,v,A], lambdas['ab'], t['ab'][pv,pA,ha,hA], optimize=True)
    HBar['b'][C,A] += 1.0 * np.einsum('IA,AU->IU', h['b'][C,V], t['b'][pV,hA], optimize=True)
    HBar['b'][C,A] += -1.0 * np.einsum('IJUV,uVvW,vWuJ->IU', h['bb'][C,C,A,A], lambdas['ab'], t['ab'][pa,pA,ha,hC], optimize=True)
    HBar['b'][C,A] += -0.5 * np.einsum('IJUV,VWXY,XYJW->IU', h['bb'][C,C,A,A], lambdas['bb'], t['bb'][pA,pA,hC,hA], optimize=True)
    HBar['b'][C,A] += 1.0 * np.einsum('IJUA,AJ->IU', h['bb'][C,C,A,V], t['b'][pV,hC], optimize=True)
    HBar['b'][C,A] += -0.25 * np.einsum('IJVW,VWXY,XYJU->IU', h['bb'][C,C,A,A], lambdas['bb'], t['bb'][pA,pA,hC,hA], optimize=True)
    HBar['b'][C,A] += -0.5 * np.einsum('IJAB,ABJU->IU', h['bb'][C,C,V,V], t['bb'][pV,pV,hC,hA], optimize=True)
    HBar['b'][C,A] += 1.0 * np.einsum('IVUA,uWvV,vAuW->IU', h['bb'][C,A,A,V], lambdas['ab'], t['ab'][pa,pV,ha,hA], optimize=True)
    HBar['b'][C,A] += -0.5 * np.einsum('IVUA,WXVY,YAWX->IU', h['bb'][C,A,A,V], lambdas['bb'], t['bb'][pA,pV,hA,hA], optimize=True)
    HBar['b'][C,A] += -1.0 * np.einsum('IVWA,uWvV,vAuU->IU', h['bb'][C,A,A,V], lambdas['ab'], t['ab'][pa,pV,ha,hA], optimize=True)
    HBar['b'][C,A] += 1.0 * np.einsum('IVWA,WXVY,YAUX->IU', h['bb'][C,A,A,V], lambdas['bb'], t['bb'][pA,pV,hA,hA], optimize=True)
    # A|V
    HBar['b'][V,A] += -1.0 * np.einsum('uv,wx,vw,xAuU->AU', eta1['a'], gamma1['a'], h['a'][a,a], t['ab'][pa,pV,ha,hA], optimize=True)
    HBar['b'][V,A] += 1.0 * np.einsum('uv,wx,xu,vAwU->AU', eta1['a'], gamma1['a'], h['a'][a,a], t['ab'][pa,pV,ha,hA], optimize=True)
    HBar['b'][V,A] += -1.0 * np.einsum('uv,wx,xIuU,vAwI->AU', eta1['a'], gamma1['a'], h['ab'][a,C,a,A], t['ab'][pa,pV,ha,hC], optimize=True)
