    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('uv,vAaB,BI,bu->bAaI', eta1['a'], h['ab'][a,V,v,V], t['b'][pV,hC], t['a'][pv,ha], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('UV,uv,vVaB,BI,bAuU->bAaI', eta1['b'], eta1['a'], h['ab'][a,A,v,V], t['b'][pV,hC], t['ab'][pv,pV,ha,hA], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('UV,uv,vJaU,AJ,bVuI->bAaI', eta1['b'], gamma1['a'], h['ab'][a,C,v,A], t['b'][pV,hC], t['ab'][pv,pA,ha,hC], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('UV,WX,iVaW,bi,XAIU->bAaI', eta1['b'], gamma1['b'], h['ab'][c,A,v,A], t['a'][pv,hc], t['bb'][pA,pV,hC,hA], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('UV,WX,iXaU,bi,VAIW->bAaI', eta1['b'], gamma1['b'], h['ab'][c,A,v,A], t['a'][pv,hc], t['bb'][pA,pV,hC,hA], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('UV,iJaU,bi,VAIJ->bAaI', eta1['b'], h['ab'][c,C,v,A], t['a'][pv,hc], t['bb'][pA,pV,hC,hC], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('UV,iJaU,VI,bAiJ->bAaI', eta1['b'], h['ab'][c,C,v,A], t['b'][pA,hC], t['ab'][pv,pV,hc,hC], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('UV,iJaU,VJ,bAiI->bAaI', eta1['b'], h['ab'][c,C,v,A], t['b'][pA,hC], t['ab'][pv,pV,hc,hC], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('UV,iJaU,AJ,bViI->bAaI', eta1['b'], h['ab'][c,C,v,A], t['b'][pV,hC], t['ab'][pv,pA,hc,hC], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('UV,iVaI,AU,bi->bAaI', eta1['b'], h['ab'][c,A,v,C], t['b'][pV,hA], t['a'][pv,hc], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('UV,iVaB,AU,bBiI->bAaI', eta1['b'], h['ab'][c,A,v,V], t['b'][pV,hA], t['ab'][pv,pV,hc,hC], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('UV,iAaU,VI,bi->bAaI', eta1['b'], h['ab'][c,V,v,A], t['b'][pA,hC], t['a'][pv,hc], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('UV,aJbU,AJ,VI->aAbI', eta1['b'], h['ab'][v,C,v,A], t['b'][pV,hC], t['b'][pA,hC], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('UV,aVbB,AU,BI->aAbI', eta1['b'], h['ab'][v,A,v,V], t['b'][pV,hA], t['b'][pV,hC], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('uv,ivac,bi,cAuI->bAaI', gamma1['a'], h['aa'][c,a,v,v], t['a'][pv,hc], t['ab'][pv,pV,ha,hC], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('uv,ivac,bu,cAiI->bAaI', gamma1['a'], h['aa'][c,a,v,v], t['a'][pv,ha], t['ab'][pv,pV,hc,hC], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('uv,ivac,ci,bAuI->bAaI', gamma1['a'], h['aa'][c,a,v,v], t['a'][pv,hc], t['ab'][pv,pV,ha,hC], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('uv,ivac,cu,bAiI->bAaI', gamma1['a'], h['aa'][c,a,v,v], t['a'][pv,ha], t['ab'][pv,pV,hc,hC], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('uv,vJaI,AJ,bu->bAaI', gamma1['a'], h['ab'][a,C,v,C], t['b'][pV,hC], t['a'][pv,ha], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('uv,vJaB,bu,ABIJ->bAaI', gamma1['a'], h['ab'][a,C,v,V], t['a'][pv,ha], t['bb'][pV,pV,hC,hC], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('uv,vJaB,AJ,bBuI->bAaI', gamma1['a'], h['ab'][a,C,v,V], t['b'][pV,hC], t['ab'][pv,pV,ha,hC], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('uv,vJaB,BI,bAuJ->bAaI', gamma1['a'], h['ab'][a,C,v,V], t['b'][pV,hC], t['ab'][pv,pV,ha,hC], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('uv,vJaB,BJ,bAuI->bAaI', gamma1['a'], h['ab'][a,C,v,V], t['b'][pV,hC], t['ab'][pv,pV,ha,hC], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('uv,vAaB,BI,bu->bAaI', gamma1['a'], h['ab'][a,V,v,V], t['b'][pV,hC], t['a'][pv,ha], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('UV,uv,vVaB,BI,bAuU->bAaI', gamma1['b'], gamma1['a'], h['ab'][a,A,v,V], t['b'][pV,hC], t['ab'][pv,pV,ha,hA], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('UV,iJaU,VI,bAiJ->bAaI', gamma1['b'], h['ab'][c,C,v,A], t['b'][pA,hC], t['ab'][pv,pV,hc,hC], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('UV,iVaI,AU,bi->bAaI', gamma1['b'], h['ab'][c,A,v,C], t['b'][pV,hA], t['a'][pv,hc], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('UV,iVaB,bi,ABIU->bAaI', gamma1['b'], h['ab'][c,A,v,V], t['a'][pv,hc], t['bb'][pV,pV,hC,hA], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('UV,iVaB,AU,bBiI->bAaI', gamma1['b'], h['ab'][c,A,v,V], t['b'][pV,hA], t['ab'][pv,pV,hc,hC], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('UV,iVaB,BI,bAiU->bAaI', gamma1['b'], h['ab'][c,A,v,V], t['b'][pV,hC], t['ab'][pv,pV,hc,hA], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('UV,iVaB,BU,bAiI->bAaI', gamma1['b'], h['ab'][c,A,v,V], t['b'][pV,hA], t['ab'][pv,pV,hc,hC], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('UV,iAaU,VI,bi->bAaI', gamma1['b'], h['ab'][c,V,v,A], t['b'][pA,hC], t['a'][pv,hc], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('UV,aJbU,AJ,VI->aAbI', gamma1['b'], h['ab'][v,C,v,A], t['b'][pV,hC], t['b'][pA,hC], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('UV,aVbB,AU,BI->aAbI', gamma1['b'], h['ab'][v,A,v,V], t['b'][pV,hA], t['b'][pV,hC], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('ijac,bi,cAjI->bAaI', h['aa'][c,c,v,v], t['a'][pv,hc], t['ab'][pv,pV,hc,hC], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('ijac,ci,bAjI->bAaI', h['aa'][c,c,v,v], t['a'][pv,hc], t['ab'][pv,pV,hc,hC], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('iJaI,AJ,bi->bAaI', h['ab'][c,C,v,C], t['b'][pV,hC], t['a'][pv,hc], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('iJaB,bi,ABIJ->bAaI', h['ab'][c,C,v,V], t['a'][pv,hc], t['bb'][pV,pV,hC,hC], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('iJaB,AJ,bBiI->bAaI', h['ab'][c,C,v,V], t['b'][pV,hC], t['ab'][pv,pV,hc,hC], optimize=True)
    HBar['ab'][v,V,v,C] += 1.0 * np.einsum('iJaB,BI,bAiJ->bAaI', h['ab'][c,C,v,V], t['b'][pV,hC], t['ab'][pv,pV,hc,hC], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('iJaB,BJ,bAiI->bAaI', h['ab'][c,C,v,V], t['b'][pV,hC], t['ab'][pv,pV,hc,hC], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('iAaB,BI,bi->bAaI', h['ab'][c,V,v,V], t['b'][pV,hC], t['a'][pv,hc], optimize=True)
    HBar['ab'][v,V,v,C] += -1.0 * np.einsum('aJbB,AJ,BI->aAbI', h['ab'][v,C,v,V], t['b'][pV,hC], t['b'][pV,hC], optimize=True)
    # vV|Aa
    # vV|Av
    HBar['ab'][v,A,v,V] += 1.0 * np.einsum('iIaA,UI,bi->bUaA', h['ab'][c,C,v,V], t['b'][pA,hC], t['a'][pv,hc], optimize=True)
    # vV|Cv
    # vV|Va
    HBar['ab'][a,V,v,V] += 1.0 * np.einsum('iIaA,BI,ui->uBaA', h['ab'][c,C,v,V], t['b'][pV,hC], t['a'][pa,hc], optimize=True)
    # vV|Vc
    # vV|Vv
    HBar['ab'][v,V,v,V] += 1.0 * np.einsum('uv,vIaA,BI,bu->bBaA', eta1['a'], h['ab'][a,C,v,V], t['b'][pV,hC], t['a'][pv,ha], optimize=True)
    HBar['ab'][v,V,v,V] += 1.0 * np.einsum('UV,iVaA,BU,bi->bBaA', eta1['b'], h['ab'][c,A,v,V], t['b'][pV,hA], t['a'][pv,hc], optimize=True)
    HBar['ab'][v,V,v,V] += 1.0 * np.einsum('uv,vIaA,BI,bu->bBaA', gamma1['a'], h['ab'][a,C,v,V], t['b'][pV,hC], t['a'][pv,ha], optimize=True)
    HBar['ab'][v,V,v,V] += 1.0 * np.einsum('UV,iVaA,BU,bi->bBaA', gamma1['b'], h['ab'][c,A,v,V], t['b'][pV,hA], t['a'][pv,hc], optimize=True)
    HBar['ab'][v,V,v,V] += 1.0 * np.einsum('iIaA,BI,bi->bBaA', h['ab'][c,C,v,V], t['b'][pV,hC], t['a'][pv,hc], optimize=True)
    # vv|aa
    # vv|va
    HBar['aa'][a,v,v,v] += -0.5 * np.einsum('ijab,ci,uj->ucab', h['aa'][c,c,v,v], t['a'][pv,hc], t['a'][pa,hc], optimize=True)
    # vv|vc
    # vv|vv
    HBar['aa'][v,v,v,v] += -0.5 * np.einsum('uv,ivab,cu,di->cdab', eta1['a'], h['aa'][c,a,v,v], t['a'][pv,ha], t['a'][pv,hc], optimize=True)
    HBar['aa'][v,v,v,v] += -0.5 * np.einsum('uv,ivab,cu,di->cdab', gamma1['a'], h['aa'][c,a,v,v], t['a'][pv,ha], t['a'][pv,hc], optimize=True)
    HBar['aa'][v,v,v,v] += 0.25 * np.einsum('ijab,ci,dj->cdab', h['aa'][c,c,v,v], t['a'][pv,hc], t['a'][pv,hc], optimize=True)
    toc = time.time()
    elapsed_time = toc - tic
    if verbose:
            print(f'Took {elapsed_time} seconds.')
    return HBar
